using System;
using System.IO;
using System.Net;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
namespace Shixun {
public sealed class FetchResult {public int status;public double upstreamUpdated;public string text="",etag="",modified="",contentType="",location="";public byte[] bytes;public Uri finalUri;}
public static class Transport {
 public static double FeedUpdated(string value){DateTimeOffset timestamp;if(!String.IsNullOrWhiteSpace(value)&&DateTimeOffset.TryParse(value,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.AssumeUniversal,out timestamp))return (timestamp.ToUniversalTime()-new DateTimeOffset(1970,1,1,0,0,0,TimeSpan.Zero)).TotalMilliseconds;return 0;}
 public static string Decode(byte[] bytes,string contentType){Encoding encoding=Encoding.UTF8;try{var charset=Regex.Match(contentType??"","charset\\s*=\\s*[\"\u0027]?([^;\\s\"\u0027]+)",RegexOptions.IgnoreCase);if(charset.Success)encoding=Encoding.GetEncoding(charset.Groups[1].Value);else if(bytes.Length>1&&bytes[0]==255&&bytes[1]==254)encoding=Encoding.Unicode;else if(bytes.Length>1&&bytes[0]==254&&bytes[1]==255)encoding=Encoding.BigEndianUnicode;else{string prefix=Encoding.ASCII.GetString(bytes,0,Math.Min(200,bytes.Length));var declaration=Regex.Match(prefix,"<\\?xml[^>]*encoding\\s*=\\s*[\"\u0027]([^\"\u0027]+)",RegexOptions.IgnoreCase);if(declaration.Success)encoding=Encoding.GetEncoding(declaration.Groups[1].Value);}}catch{}return encoding.GetString(bytes).TrimStart('\uFEFF');}
 public static Uri ValidateUrl(string text){Uri uri;if(!Uri.TryCreate(text,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&uri.Scheme!="http")||!String.IsNullOrEmpty(uri.UserInfo)||text.Length>8192||text.IndexOfAny(new[]{'\r','\n'})>=0)throw new SafeError("请输入不含账号密码的 HTTP(S) 地址。");return uri;}
 public static string GitHubUrl(string text){var u=ValidateUrl(text);if(u.Host=="github.com"){var s=u.AbsolutePath.Split('/');if(s.Length>=6&&s[3]=="blob")return "https://api.github.com/repos/"+s[1]+"/"+s[2]+"/contents/"+String.Join("/",s.Skip(5))+"?ref="+Uri.EscapeDataString(s[4]);}return text;}
 public static void ValidateProfile(RequestProfile p){if(p==null||p.fields==null||p.fields.Count>60||!new[]{"GET","POST"}.Contains(p.method)||!new[]{"none","bearer","basic"}.Contains(p.mode)||p.body==null||p.body.Length>256000||p.token==null||p.username==null||p.password==null||p.contentType==null||p.token.IndexOfAny(new[]{'\r','\n'})>=0||p.contentType.IndexOfAny(new[]{'\r','\n'})>=0)throw new SafeError("请求配置格式无效。");foreach(var f in p.fields){if(f==null||!new[]{"header","query","path","form"}.Contains(f.place)||String.IsNullOrWhiteSpace(f.name)||f.name.Length>120||f.value.Length>32000)throw new SafeError("参数名称、位置或长度无效。");if(f.place=="header"&&(!Regex.IsMatch(f.name,"^[A-Za-z0-9!#$%&'*+.^_`|~-]+$")||f.value.IndexOfAny(new[]{'\r','\n'})>=0||new[]{"host","content-length","connection","transfer-encoding","proxy-authorization"}.Contains(f.name.ToLowerInvariant())))throw new SafeError("请求头包含不允许的名称或换行。");}if(p.fields.Any(f=>f.place=="form")&&p.method!="POST")throw new SafeError("表单参数需要 POST 请求。");if(p.mode!="none"&&p.fields.Any(f=>f.place=="header"&&f.name.Equals("Authorization",StringComparison.OrdinalIgnoreCase)))throw new SafeError("认证模式和自定义 Authorization 头不能同时配置。");}
 public static string RequestUrl(string url,RequestProfile profile){string result=url;foreach(var f in profile.fields.Where(f=>f.place=="path"))result=result.Replace("{"+f.name+"}",Uri.EscapeDataString(f.value));if(Regex.IsMatch(result,"\\{[^}]+\\}"))throw new SafeError("URL 路径占位参数未配置完整。");var builder=new UriBuilder(ValidateUrl(result));var query=builder.Query.TrimStart('?');foreach(var f in profile.fields.Where(f=>f.place=="query"))query+=(query.Length>0?"&":"")+Uri.EscapeDataString(f.name)+"="+Uri.EscapeDataString(f.value);builder.Query=query;return builder.Uri.AbsoluteUri;}
 public static FetchResult Fetch(string url,RequestProfile profile,string etag="",string modified="",int limit=4*1024*1024,int timeout=25000){
  profile=profile??new RequestProfile();ValidateProfile(profile);Uri current=ValidateUrl(RequestUrl(url,profile));bool authenticated=profile.HasSecrets();if(authenticated&&current.Scheme!="https"&&!current.IsLoopback)throw new SafeError("带凭据的请求必须使用 HTTPS。");
  ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;
  for(int hop=0;hop<5;hop++){
   var request=(HttpWebRequest)WebRequest.Create(current);request.AllowAutoRedirect=false;request.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;request.Timeout=timeout;request.ReadWriteTimeout=timeout;request.Method=profile.method;request.UserAgent="Shixun/1.0 RSS Reader";request.Accept=current.Host=="api.github.com"?"application/vnd.github.raw+json":"application/rss+xml, application/atom+xml, application/json, text/xml, */*";
   if(profile.mode=="bearer")request.Headers["Authorization"]="Bearer "+profile.token;
   if(profile.mode=="basic")request.Headers["Authorization"]="Basic "+Convert.ToBase64String(Encoding.UTF8.GetBytes(profile.username+":"+profile.password));
   foreach(var f in profile.fields.Where(f=>f.place=="header")){if(f.name.Equals("User-Agent",StringComparison.OrdinalIgnoreCase))request.UserAgent=f.value;else if(f.name.Equals("Accept",StringComparison.OrdinalIgnoreCase))request.Accept=f.value;else if(f.name.Equals("Referer",StringComparison.OrdinalIgnoreCase))request.Referer=f.value;else if(f.name.Equals("Content-Type",StringComparison.OrdinalIgnoreCase))request.ContentType=f.value;else request.Headers[f.name]=f.value;}
   if(!String.IsNullOrEmpty(etag))request.Headers["If-None-Match"]=etag;
   DateTime modifiedDate;if(DateTime.TryParse(modified,out modifiedDate))request.IfModifiedSince=modifiedDate;
   if(profile.method=="POST"){var form=profile.fields.Where(f=>f.place=="form").ToList();string body=form.Count>0?String.Join("&",form.Select(f=>Uri.EscapeDataString(f.name)+"="+Uri.EscapeDataString(f.value))):profile.body;request.ContentType=form.Count>0?"application/x-www-form-urlencoded":profile.contentType;var bytes=Encoding.UTF8.GetBytes(body);request.ContentLength=bytes.Length;using(var stream=request.GetRequestStream())stream.Write(bytes,0,bytes.Length);}
   HttpWebResponse response=null;
   try{response=(HttpWebResponse)request.GetResponse();}catch(WebException ex){response=ex.Response as HttpWebResponse;if(response==null)throw new SafeError(ex.Status==WebExceptionStatus.Timeout?"请求超时，稍后重试。":"连接失败，请检查网络或地址。");}
   using(response){int status=(int)response.StatusCode;
    if(status>=300&&status<400&&status!=304){var location=response.Headers["Location"];Uri next;if(!Uri.TryCreate(current,location,out next))throw new SafeError("重定向地址无效。");ValidateUrl(next.AbsoluteUri);if(current.Scheme=="https"&&next.Scheme!="https")throw new SafeError("已阻止 HTTPS 降级重定向。");if(authenticated&&(current.Scheme!=next.Scheme||current.Host!=next.Host||current.Port!=next.Port))throw new SafeError("已阻止带凭据的跨站重定向，请填写最终地址。");if(profile.method!="GET")throw new SafeError("POST 重定向需要手动配置最终地址。");current=next;continue;}
    if(status==304)return new FetchResult{upstreamUpdated=FeedUpdated(response.Headers["X-Feed-Updated-At"]),status=status,finalUri=current};
    if(status<200||status>=300){int retry=0;int.TryParse(response.Headers["Retry-After"],out retry);DateTimeOffset at;if(retry==0&&DateTimeOffset.TryParse(response.Headers["Retry-After"],out at))retry=(int)Math.Max(0,(at-DateTimeOffset.UtcNow).TotalSeconds);throw new SafeError(status==401||status==403?"认证失败或无访问权限，请检查该源的凭据。":status==429?"服务限流，已延后重试。":"HTTP "+status+"，请检查地址或服务状态。",Math.Min(86400,Math.Max(0,retry)));}
    if(response.ContentLength>limit)throw new SafeError("响应超过大小限制。");using(var stream=response.GetResponseStream())using(var memory=new MemoryStream()){byte[] buffer=new byte[8192];int count;while((count=stream.Read(buffer,0,buffer.Length))>0){if(memory.Length+count>limit)throw new SafeError("响应超过大小限制。");memory.Write(buffer,0,count);}var data=memory.ToArray();Encoding encoding=Encoding.UTF8;try{if(!String.IsNullOrEmpty(response.CharacterSet))encoding=Encoding.GetEncoding(response.CharacterSet);}catch{}return new FetchResult{upstreamUpdated=FeedUpdated(response.Headers["X-Feed-Updated-At"]),status=status,text=Decode(data,response.ContentType),bytes=data,contentType=response.ContentType,etag=response.Headers["ETag"]??"",modified=response.Headers["Last-Modified"]??"",finalUri=current};}
   }
  }throw new SafeError("重定向次数过多。");
 }
}
}
